package com.linkforty.sdk.models

import com.squareup.moshi.JsonClass

/**
 * Response from the install attribution API.
 */
@JsonClass(generateAdapter = true)
data class InstallResponse @JvmOverloads constructor(
    /** Unique install ID generated by the backend */
    val installId: String,

    /** Whether this install was attributed to a link click */
    val attributed: Boolean,

    /** Confidence score for attribution (0-100) */
    val confidenceScore: Double,

    /** Which factors matched: the fingerprint factors, or `["install_referrer"]` */
    val matchedFactors: List<String>,

    /** Deep link data if attributed, null if organic */
    val deepLinkData: DeepLinkData? = null,

    /**
     * How the install was attributed: `"install_referrer"` when the Google Play
     * install referrer named the click, `"fingerprint"` when it was matched to a
     * click by device fingerprint, `"none"` when it is organic. Null when the server does not send it,
     * and on launches after the first, which return the attribution stored on
     * the device.
     */
    val attributionMethod: String? = null,

    /**
     * How many other links had a click from the install's network that also
     * reached the confidence threshold. Above 0, a tap on another device on the
     * same network may be what led to this install, so an app acting on a
     * sensitive link (a sign-in or a gift) can treat the match as unverified,
     * for example by asking the user to confirm. 0 when nothing else was in
     * contention and for organic installs; null when the server does not send it,
     * and on launches after the first.
     */
    val competingLinks: Int? = null
)
